package com.insight.quantlife.tests;
import android.app.*;import android.os.*;import org.json.*;import java.io.*;import com.insight.quantlife.*;
/** Opt-in paid provider test on the isolated emulator. Key supplied only in memory. */
public final class IllustrationLiveTest extends DocumentEditorTest {
 String liveKey;@Override public void onCreate(Bundle args){liveKey=args==null?null:args.getString("liveKey");start();}
 @Override public void onStart(){Bundle out=new Bundle();JSONObject previous=null;try{
  if(liveKey==null||liveKey.isEmpty())throw new Exception("Provide ephemeral liveKey argument explicitly");
  h=new MainHost(this);h.open();h.js("AutoWiki.kick=()=>{};AutoWiki.resume=()=>{}");
  java.lang.reflect.Method privateSettings=h.activity.getClass().getDeclaredMethod("privateSettings");privateSettings.setAccessible(true);previous=new JSONObject(((JSONObject)privateSettings.invoke(h.activity)).toString());
  h.call("saveSettings",new JSONObject().put("settings",new JSONObject().put("profile",new JSONObject().put("id","custom").put("label","Live reference QA").put("baseUrl","https://dashscope.aliyuncs.com/compatible-mode/v1").put("model","deepseek-v4.1-flash").put("protocol","chat").put("effort","off").put("apiKey",liveKey))));
  h.call("saveImageSettings",new JSONObject().put("settings",new JSONObject().put("apiKey",liveKey).put("model","qwen-image-2.1-turbo")));liveKey=null;
  File file=new File(getTargetContext().getFilesDir(),"qa/live-reference.jpg");JSONObject ref=RecordMedia.fromBytes(getTargetContext(),java.nio.file.Files.readAllBytes(file.toPath()),"RAG图解风格参考");
  open("learning");String body="这套 PageIndex+wiki 方案，总结起来就一句话：让知识库变得可长期积累且可维护，并能让系统可以支持强逻辑，强语义召回的能力。相比之下，传统的RAG，每次召回都像发现了新知识，而不是积累知识，随着未来文本模型的成本越来越低，向量检索的方式，或许只会成为历史的方案被尘封起来。";input("PageIndex 与 Wiki · 配图验证",body);
  h.js("window.__added=false;RecordEditor.image("+ref+").then(()=>__added=true)");until("__added");
  h.js("(()=>{const b=document.querySelector('#doc-body'),w=document.createTreeWalker(b,NodeFilter.SHOW_TEXT);let n;while(n=w.nextNode()){if(n.textContent.includes('这套')){const r=document.createRange();r.selectNodeContents(n);b.focus();getSelection().removeAllRanges();getSelection().addRange(r);document.dispatchEvent(new Event('selectionchange'));return;}}})()");Thread.sleep(200);click("#doc-illustrate");until("!!document.querySelector('#illustration-reference')");
  h.js("document.querySelector('#illustration-reference').value="+JSONObject.quote(ref.getString("id"))+";document.querySelector('#illustration-reference').dispatchEvent(new Event('change'))");click("#illustration-prompt-auto");
  boolean planned=false;for(int i=0;i<180;i++){if(h.js("document.querySelector('#illustration-prompt').value.length>0").equals("true")){planned=true;break;}Thread.sleep(1000);}check(planned,"Actual App visual planner returns editable prompt from selected text and reference pixels");
  String prompt=new JSONArray("["+h.js("document.querySelector('#illustration-prompt').value")+"]").getString(0);try(FileOutputStream stream=new FileOutputStream(new File(getTargetContext().getFilesDir(),"qa/live-app-prompt.txt"))){stream.write(prompt.getBytes("UTF-8"));}
  h.screenshot("live-app-plan.png");String recordId=new JSONArray("["+h.js("RecordEditor.illustrationRecordId()")+"]").getString(0);click("#illustration-generate");String jobId="";for(int n=0;n<40;n++){JSONArray all=(JSONArray)h.call("getIllustrationJobs",new JSONObject());for(int i=0;i<all.length();i++){JSONObject j=all.getJSONObject(i);if(recordId.equals(j.optString("recordId"))&&!j.optString("taskId").isEmpty())jobId=j.getString("id");}if(!jobId.isEmpty())break;Thread.sleep(1000);}check(!jobId.isEmpty(),"Actual App submits one Qwen image task and persists provider ID");
  click("#illustration-close");check(h.js("document.querySelectorAll('#doc-body img').length===1").equals("true"),"Submitting image never auto inserts into original selection");
  // Restore chat profile before restart, so unrelated automatic Wiki QA cannot use a live key.
  JSONObject oldProfile=previous.getJSONObject("profiles").getJSONObject(previous.getString("activeProfile"));h.call("saveSettings",new JSONObject().put("settings",new JSONObject().put("profile",oldProfile)));
  close();runOnMainSync(()->h.activity.finish());h=new MainHost(this);h.open();h.js("AutoWiki.kick=()=>{};AutoWiki.resume=()=>{}");JSONObject ready=null;
  for(int n=0;n<180;n++){JSONArray all=(JSONArray)h.call("getIllustrationJobs",new JSONObject());for(int i=0;i<all.length();i++){JSONObject j=all.getJSONObject(i);if(jobId.equals(j.optString("id"))){if("READY".equals(j.optString("status")))ready=j;if("FAILED|UNKNOWN|UNCERTAIN".contains(j.optString("status")))throw new Exception("Live image task ended with "+j.optString("status"));}}if(ready!=null)break;Thread.sleep(1000);}
  check(ready!=null,"App restart resumes original remote task and saves real image locally");
  open("experience");input("生成图手动插入验证","这是一条新记录。生成的图像由我选择位置插入，不依赖之前的选区。");click("#doc-image");until("!!document.querySelector('[data-select]')");h.screenshot("live-app-gallery.png");click("[data-preview]");until("!!document.querySelector('#doc-image-viewer img')&&document.querySelector('#doc-image-viewer img').naturalWidth>0");check(h.js("document.querySelector('#doc-image-viewer').contains(document.elementFromPoint(innerWidth/2,innerHeight/2))").equals("true"),"Real generated image previews above the gallery overlay");h.screenshot("live-app-preview.png");click("#doc-image-close");click("[data-select]");click("#gallery-insert");until("document.querySelectorAll('#doc-body img').length===1");h.screenshot("live-app-inserted.png");saveUI();check(true,"Real generated image manually inserts into new record and saves");
  out.putString("stream","PASS IllustrationLiveTest: "+passed+" checks\n");finish(Activity.RESULT_OK,out);
 }catch(Throwable ex){out.putString("stream","FAIL IllustrationLiveTest after "+passed+": "+ex.getClass().getSimpleName()+" "+String.valueOf(ex.getMessage()).replaceAll("sk-[A-Za-z0-9_.-]+","[hidden]")+"\n");finish(Activity.RESULT_CANCELED,out);}
 finally{liveKey=null;if(previous!=null&&h!=null){try{java.lang.reflect.Method encrypt=h.activity.getClass().getDeclaredMethod("encryptSettings",JSONObject.class);encrypt.setAccessible(true);encrypt.invoke(h.activity,previous);}catch(Exception ignored){}}}}
}
